  "Notruf 112 anrufen": { en: "Call emergency number 112", es: "Llamar al número de emergencias 112", ar: "الاتصال برقم الطوارئ 112" },
  "Lebensgefahr? Ruf sofort **112** an.": { en: "Danger to life? Call **112** now.", es: "¿Peligro de muerte? Llama ya al **112**.", ar: "خطر على الحياة؟ اتصل فورًا بـ **112**." },
  "Im Zweifel: Notruf **112**.": { en: "If in doubt: emergency number **112**.", es: "En caso de duda: número de emergencias **112**.", ar: "عند الشك: رقم الطوارئ **112**." },
